-- Generated by `pnpm --filter @carbon/database authz migration` from packages/database/src/authz. Do not edit.

-- Ships these rules to databases where `authz sync` does not run after migrations yet.

CREATE OR REPLACE FUNCTION public.apply_item_stock_quantities()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- quantityNonNettable is the part of quantityOnHand that sits in a storage
  -- unit whose effectiveNettable is false. A row with no storage unit, or one
  -- whose unit no longer exists, is nettable.
  IF TG_OP = 'INSERT' THEN
    INSERT INTO "itemStockQuantities" AS isq
      ("itemId", "companyId", "locationId", "projectId", "quantityOnHand", "quantityNonNettable")
    SELECT
      b."itemId",
      b."companyId",
      COALESCE(b."locationId", ''),
      COALESCE(b."projectId", ''),
      SUM(item_ledger_on_hand_contribution(b."quantity", b."trackedEntityStatus")),
      COALESCE(SUM(item_ledger_on_hand_contribution(b."quantity", b."trackedEntityStatus"))
        FILTER (WHERE su."effectiveNettable" = false), 0)
    FROM batched_new b
    LEFT JOIN "storageUnit" su ON su."id" = b."storageUnitId"
    GROUP BY b."itemId", b."companyId", COALESCE(b."locationId", ''), COALESCE(b."projectId", '')
    ORDER BY 1, 2, 3, 4
    ON CONFLICT ("itemId", "companyId", "locationId", "projectId")
    DO UPDATE SET
      "quantityOnHand" = isq."quantityOnHand" + EXCLUDED."quantityOnHand",
      "quantityNonNettable" = isq."quantityNonNettable" + EXCLUDED."quantityNonNettable";

  ELSIF TG_OP = 'UPDATE' THEN
    -- Generic old-vs-new: subtract every old row's contribution at its old key
    -- and add every new row's at its new key. Covers the real case (a
    -- trackedEntityStatus flip) and any future quantity/location/item edit
    -- without special-casing.
    INSERT INTO "itemStockQuantities" AS isq
      ("itemId", "companyId", "locationId", "projectId", "quantityOnHand", "quantityNonNettable")
    SELECT "itemId", "companyId", "locationId", "projectId", SUM(delta), SUM(non_nettable_delta)
    FROM (
      SELECT
        b."itemId",
        b."companyId",
        COALESCE(b."locationId", '') AS "locationId",
        COALESCE(b."projectId", '') AS "projectId",
        -item_ledger_on_hand_contribution(b."quantity", b."trackedEntityStatus") AS delta,
        CASE WHEN su."effectiveNettable" = false
          THEN -item_ledger_on_hand_contribution(b."quantity", b."trackedEntityStatus")
          ELSE 0
        END AS non_nettable_delta
      FROM batched_old b
      LEFT JOIN "storageUnit" su ON su."id" = b."storageUnitId"
      UNION ALL
      SELECT
        b."itemId",
        b."companyId",
        COALESCE(b."locationId", ''),
        COALESCE(b."projectId", ''),
        item_ledger_on_hand_contribution(b."quantity", b."trackedEntityStatus"),
        CASE WHEN su."effectiveNettable" = false
          THEN item_ledger_on_hand_contribution(b."quantity", b."trackedEntityStatus")
          ELSE 0
        END
      FROM batched_new b
      LEFT JOIN "storageUnit" su ON su."id" = b."storageUnitId"
    ) d
    GROUP BY "itemId", "companyId", "locationId", "projectId"
    -- A key whose net deltas are zero already holds the right numbers; skipping
    -- it avoids taking a lock on every row a wide UPDATE happened to touch.
    HAVING SUM(delta) <> 0 OR SUM(non_nettable_delta) <> 0
    ORDER BY 1, 2, 3, 4
    ON CONFLICT ("itemId", "companyId", "locationId", "projectId")
    DO UPDATE SET
      "quantityOnHand" = isq."quantityOnHand" + EXCLUDED."quantityOnHand",
      "quantityNonNettable" = isq."quantityNonNettable" + EXCLUDED."quantityNonNettable";

  ELSIF TG_OP = 'DELETE' THEN
    -- Defensive: no application path deletes itemLedger rows today. A key left
    -- at zero with no backing ledger rows is removed by the nightly
    -- reconciliation.
    INSERT INTO "itemStockQuantities" AS isq
      ("itemId", "companyId", "locationId", "projectId", "quantityOnHand", "quantityNonNettable")
    SELECT
      b."itemId",
      b."companyId",
      COALESCE(b."locationId", ''),
      COALESCE(b."projectId", ''),
      -SUM(item_ledger_on_hand_contribution(b."quantity", b."trackedEntityStatus")),
      -COALESCE(SUM(item_ledger_on_hand_contribution(b."quantity", b."trackedEntityStatus"))
        FILTER (WHERE su."effectiveNettable" = false), 0)
    FROM batched_old b
    LEFT JOIN "storageUnit" su ON su."id" = b."storageUnitId"
    GROUP BY b."itemId", b."companyId", COALESCE(b."locationId", ''), COALESCE(b."projectId", '')
    ORDER BY 1, 2, 3, 4
    ON CONFLICT ("itemId", "companyId", "locationId", "projectId")
    DO UPDATE SET
      "quantityOnHand" = isq."quantityOnHand" + EXCLUDED."quantityOnHand",
      "quantityNonNettable" = isq."quantityNonNettable" + EXCLUDED."quantityNonNettable";
  END IF;

  RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION public.storage_unit_release_non_nettable_stock(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF p_operation <> 'DELETE' THEN
    RETURN;
  END IF;

  IF COALESCE((p_old->>'effectiveNettable')::boolean, true) THEN
    RETURN;
  END IF;

  -- Deleting a unit sets its ledger rows' storageUnitId to NULL (the FK is ON
  -- DELETE SET NULL), and stock in no unit is nettable. The ledger handler
  -- cannot tell that this stock was non-nettable, because by then the unit row
  -- is gone. So release it here, before the row is deleted. Stock is kept per
  -- project stripe, so each stripe's row is released on its own.
  INSERT INTO "itemStockQuantities" AS isq
    ("itemId", "companyId", "locationId", "projectId", "quantityOnHand", "quantityNonNettable")
  SELECT
    il."itemId",
    il."companyId",
    COALESCE(il."locationId", ''),
    COALESCE(il."projectId", ''),
    0,
    -SUM(item_ledger_on_hand_contribution(il."quantity", il."trackedEntityStatus"))
  FROM "itemLedger" il
  WHERE il."storageUnitId" = p_old->>'id'
  GROUP BY il."itemId", il."companyId", COALESCE(il."locationId", ''), COALESCE(il."projectId", '')
  HAVING SUM(item_ledger_on_hand_contribution(il."quantity", il."trackedEntityStatus")) <> 0
  ORDER BY 1, 2, 3, 4
  ON CONFLICT ("itemId", "companyId", "locationId", "projectId")
  DO UPDATE SET "quantityNonNettable" = isq."quantityNonNettable" + EXCLUDED."quantityNonNettable";
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_advance_document_sequence(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_column text;
  v_sequence text;
  v_value text;
BEGIN
  -- A document saved with a number in its sequence's format (typed by hand,
  -- sent through the API or MCP, imported) moves the counter past it, so
  -- get_next_sequence never hands that number out again.
  IF p_operation NOT IN ('INSERT', 'UPDATE') THEN
    RETURN;
  END IF;

  -- A new numbered table is added here and attached in attachments.ts.
  v_column := CASE p_table
    WHEN 'changeOrder' THEN 'changeOrderId'
    WHEN 'customer' THEN 'readableId'
    WHEN 'customerContract' THEN 'customerContractId'
    WHEN 'depreciationRun' THEN 'depreciationRunId'
    WHEN 'fixedAsset' THEN 'fixedAssetId'
    WHEN 'gauge' THEN 'gaugeId'
    WHEN 'inventoryCount' THEN 'inventoryCountId'
    WHEN 'job' THEN 'jobId'
    WHEN 'journal' THEN 'journalEntryId'
    WHEN 'kanban' THEN 'kanbanId'
    WHEN 'lease' THEN 'leaseId'
    WHEN 'maintenanceDispatch' THEN 'maintenanceDispatchId'
    WHEN 'memo' THEN 'memoId'
    WHEN 'nonConformance' THEN 'nonConformanceId'
    WHEN 'payment' THEN 'paymentId'
    WHEN 'pickingList' THEN 'pickingListId'
    WHEN 'purchaseInvoice' THEN 'invoiceId'
    WHEN 'purchaseOrder' THEN 'purchaseOrderId'
    WHEN 'purchaseReturnOrder' THEN 'purchaseReturnOrderId'
    WHEN 'purchasingRfq' THEN 'rfqId'
    WHEN 'quote' THEN 'quoteId'
    WHEN 'receipt' THEN 'receiptId'
    WHEN 'rentalAgreement' THEN 'rentalAgreementId'
    WHEN 'salesInvoice' THEN 'invoiceId'
    WHEN 'salesOrder' THEN 'salesOrderId'
    WHEN 'salesReturnOrder' THEN 'salesReturnOrderId'
    WHEN 'salesRfq' THEN 'rfqId'
    WHEN 'serviceJob' THEN 'serviceJobId'
    WHEN 'shipment' THEN 'shipmentId'
    WHEN 'stockTransfer' THEN 'stockTransferId'
    WHEN 'supplier' THEN 'readableId'
    WHEN 'supplierQuote' THEN 'supplierQuoteId'
    WHEN 'warehouseTransfer' THEN 'transferId'
  END;

  IF v_column IS NULL THEN
    RETURN;
  END IF;

  v_value := p_new->>v_column;
  IF v_value IS NULL
    OR (p_operation = 'UPDATE' AND v_value IS NOT DISTINCT FROM p_old->>v_column)
  THEN
    RETURN;
  END IF;

  -- The sequence is named after its table, except these.
  v_sequence := CASE
    WHEN p_table = 'journal' THEN 'journalEntry'
    WHEN p_table = 'memo' AND p_new->>'direction' = 'Debit' THEN 'debitMemo'
    WHEN p_table = 'memo' THEN 'creditMemo'
    ELSE p_table
  END;

  UPDATE "sequence"
  SET "next" = util.document_sequence_number(v_value, "prefix", "suffix", "size")::integer,
      "updatedBy" = 'system'
  WHERE "table" = v_sequence
    AND "companyId" = p_new->>'companyId'
    AND util.document_sequence_number(v_value, "prefix", "suffix", "size")
      BETWEEN "next"::bigint + 1 AND 2147483647;
END;
$function$;
